/// <summary>
/// Class to handle the AVARUMCashSales form.
/// </summary>
[Form]
public class AVARUMCashSales extends FormRun
{
    private AVARUMCashSalesDeskManager cashSalesDeskManager = null;
    SalesTableForm salesTableForm;
    private str myUrlParam;

}

private AVARUMCashSalesDeskManager parmCashSalesDeskManager()
{
    if (this.cashSalesDeskManager == null)
    {
        this.initCashSalesDeskManager();
    }

    return this.cashSalesDeskManager;
}

private void initCashSalesDeskManager()
{           
    this.cashSalesDeskManager = AVARUMCashSalesDeskManager::construct(AVARUMCashSalesDesk.Id);
}

/// <summary>
/// Sets the cash sales desk buttons.
/// </summary>
private void setCashSalesDeskButtons()
{
    AVARUMCashSalesDeskOpen.enabled(false);
    AVARUMCashSalesDeskClose.enabled(false);

    if (AVARUMCashSalesDesk)
    {
        switch (AVARUMCashSalesDesk.State)
        {
            case AVARUMCashSalesDeskState::Open:
                if (!SalesLine)   // if salesLine => there is still an open bon!
                {   
                    AVARUMCashSalesDeskClose.enabled(true);
                }                    
                break;

            case AVARUMCashSalesDeskState::Closed:
                AVARUMCashSalesDeskOpen.enabled(true);
                break;
        }
    }
}

/// <summary>
/// Sets the last used cash sales desk id if it exists.
/// </summary>
private void setLastUsedCashSalesDeskId()
{
    AVARUMCashSalesDeskId lastCashSalesDeskId;

    lastCashSalesDeskId = AVARUMCashSalesDeskManager::getLastCashSalesDeskId();
    CashSalesDeskSelectionCtrl.text(lastCashSalesDeskId);
    CashSalesDeskSelectionCtrl.modified();
}

/// <summary>
/// Sets the focus to a control on the form based on validation.
/// </summary>
private void setControlFocus()
{         
    FormControl ctrl;

    element.setCashSalesDeskButtons();

    if (this.parmCashSalesDeskManager().isValid(true))
    {
        ctrl = InputCtrl;
    }
    else
    {               
        ctrl = CashSalesDeskSelectionCtrl;
    }

    ctrl.setFocus();
}

private void setControlFocusAsync(AsyncTaskResult _result)
{    
    /// Check if the form is closed before performing any action.
    if (!element.closed()) 
    {
        this.setControlFocus();
    }
}

private void registerSetControlFocusAsync(int delayInMs = 200)
{
    element.setTimeoutEx(formMethodStr(AVARUMCashSales, setControlFocusAsync), conNull(), delayInMs);
}

private void handleInput()
{
    str input=InputCtrl.text();
    input=strltrim(strLRTrim(input));

    element.parmCashSalesDeskManager().processInput(SalesTable.SalesId, input);

    InputCtrl.text(AVAConstants::emptyString);

    SalesTable_DS.research(true);
    InputCtrl.allowEdit(true);

    element.registerSetControlFocusAsync();
}

private void handleInputAsync(AsyncTaskResult _result)
{
    this.handleInput();
}

private void validatAndSetControlState()
{
    CashSalesTab.enabled(false);
    SalesLineTab.enabled(false);

    if (this.parmCashSalesDeskManager().isValid())
    {
        //infolog.clear(0);

        CashSalesTab.enabled(true);
        SalesLineTab.enabled(true);
    }
}

/// <summary>
/// Initializes the form.
/// </summary>
public void init()
{
    super();

    this.setLastUsedCashSalesDeskId();

    myUrlParam = System.Web.HttpUtility::ParseQueryString(URLUtility::getUrl()).Get('avaDebug');
}

/// <summary>
/// Run method for the form.
/// </summary>
public void run()
{
    #SysSystemDefinedButtons

    /// Re-arrange the controls for input group and totals group on the form.
    /// This useful for better user experience and to make the form more readable
    /// and is more allinged with the buisness requirements.
    CashSalesInputGroup.arrangeMethod(FormArrangeMethod::HorizontalFlushLeft);
    CashSalesTotalsGroup.arrangeMethod(FormArrangeMethod::HorizontalFlushLeft);

    super();

    FormCommandButtonControl saveButton = this.control(this.controlId(#SystemDefinedSaveButton)) as FormCommandButtonControl;

    if (saveButton)
    {
        saveButton.visible(false);
    }
}

/// <summary>
/// Refreshes the context of the form.
/// </summary>
private void refreshContext()
{
    if (cashSalesDeskManager)
    {
        cashSalesDeskManager.reloadCashSalesDesk();
    }        
    AVARUMCashSalesDesk_ds.executeQuery();
    SalesTable_ds.executeQuery();

    this.registerSetControlFocusAsync();
}

private void setSalesTotals()
{
    SalesTotals totals;
    SalesAmount toalAmount;
    TaxAmount totalTax;
    DiscAmount totalDisc;
    AmountCur totalBalance;
    AVARUMCashSalesDesk cashSalesDesk;

    cashSalesDesk = this.AVARUMCashSalesDesk;

    CashSalesTotals_NetAmount.realValue(0);
    CashSalesTotals_CashDiscount.realValue(0);
    CashSalesTotals_VATAmount.realValue(0);
    CashSalesTotals_GrossAmount.realValue(0);

    if (cashSalesDesk.State == AVARUMCashSalesDeskState::Open)
    {            
        totals = SalesTotals::construct(SalesTable, SalesUpdate::DeliverNow);  
        totals.calc();

        totalBalance = conPeek(totals.displayFields(), TradeTotals::posBalance());
        CashSalesTotals_NetAmount.realValue(totalBalance);

        totalDisc = conPeek(totals.displayFields(), TradeTotals::posCashDisc());
        CashSalesTotals_CashDiscount.realValue(totalDisc);

        totalTax = conPeek(totals.displayFields(), TradeTotals::posTaxTotal());
        CashSalesTotals_VATAmount.realValue(totalTax);

        toalAmount = conPeek(totals.displayFields(), TradeTotals::posTotalAmount());
        CashSalesTotals_GrossAmount.realValue(toalAmount);
    }

    if (cashSalesDeskManager.getGivenAmount())
    {
        CashSalesTotals_GivenAmount.realValue(cashSalesDeskManager.getGivenAmount());
        CashSalesTotals_BackAmount.realValue(cashSalesDeskManager.getGivenAmount()-toalAmount);
    }
    else
    {
        CashSalesTotals_GivenAmount.realValue(0);
        CashSalesTotals_BackAmount.realValue(0);
    }
}

/// <summary>
/// Executes the query for the cash sales desk data source.
/// </summary>
public void executeQuery()
{
    QueryBuildDataSource qbds;
    QueryBuildRange qbr;

    qbds = this.query().dataSourceTable(tableNum(AVARUMCashSalesDesk));
    qbds.clearRange(fieldNum(AVARUMCashSalesDesk, RecId));
    qbds.clearRange(fieldNum(AVARUMCashSalesDesk, Id));

    if (CashSalesDeskSelectionCtrl.text())
    {
        /// If a cash sales desk is found, add a range to return the record.
        qbr = qbds.addRange(fieldNum(AVARUMCashSalesDesk, Id));
        qbr.value(CashSalesDeskSelectionCtrl.text());
    }
    else
    {
        /// If no cash sales desk is found, add a range to return no records.
        qbr = qbds.addRange(fieldNum(AVARUMCashSalesDesk, RecId));
        qbr.value(SysQuery::value(-1));
    }   

    super();

    element.cashSalesDeskManager = null;
    element.validatAndSetControlState();
    element.setCashSalesDeskButtons();
}

/// <summary>
/// Executes the query for the sales table data source.
/// </summary>
public void executeQuery()
{
    QueryBuildDataSource qbds;
    QueryBuildRange qbr;

    qbds = this.query().dataSourceTable(tableNum(SalesTable));
    qbds.clearRange(fieldNum(SalesTable, SalesId));

    qbr = qbds.addRange(fieldNum(SalesTable, SalesId));
    qbr.value(!AVARUMCashSalesDesk ? '-1' : element.parmCashSalesDeskManager().parmSalesOrderId());

    super();                 

    if (SalesTable)
    {
        salesTableForm = SalesTableForm::construct(SalesTableFormId::None, SalesTable);
        element.setSalesTotals();
    }
}

/// <summary>
/// Writes the record.
/// </summary>
public void write()
{
    salesTableForm.salesLine_Write(SalesLine);

    super();

    SalesTable_ds.reread();
    element.setSalesTotals();
}

/// <summary>
/// Deletes the record.
/// </summary>
public void delete()
{
    super();

    SalesTable_ds.reread();
    element.setSalesTotals();
}

/// <summary>
/// add ranges
/// </summary>
public void init()
{
    super();
    QueryBuildDataSource qbds=this.query().dataSourceTable(tableNum(SalesLine));
    qbds.addRange(fieldNum(SalesLine, SalesDeliverNow)).value('!0');

    this.cacheAddMethod(tableMethodStr(SalesLine, itemName));
}

/// <summary>
/// Modified method for the sales quantity field.
/// </summary>
public void modified()
{
    super();
    SalesLine.SalesDeliverNow=SalesLine.SalesQty;
    SalesLine_DS.write();                
}

/// <summary>
/// allow no write
/// </summary>
public void write()
{
    //super();
}

/// <summary>
///  allow no delete
/// </summary>
public void delete()
{
    //super();
}

/// <summary>
/// Clicked method for the open cash sales desk button.
/// </summary>
public void clicked()
{
    super();

    element.refreshContext();
}

/// <summary>
/// Clicked method for the close cash sales desk button.
/// </summary>
public void clicked()
{
    super();

    element.refreshContext();
}

/// <summary>
/// Lookup method for the cash sales desk.
/// </summary>
public void lookup()
{
    AVARUMCashSalesDesk::lookup(this);
}

/// <summary>
/// Modified method for the cash sales desk control
/// </summary>
/// <returns>true/false</returns>
public boolean modified()
{
    boolean ret;

    ret = super();

    AVARUMCashSalesDesk_ds.executeQuery();

    if (!AVARUMCashSalesDesk)
    {
        AVARUMCashSalesDeskManager::deleteLastCashSalesDeskId();
        CashSalesDeskSelectionCtrl.text(AVAConstants::emptyString);
    }
    else
    {
        AVARUMCashSalesDeskManager::saveLastCashSalesDeskId(AVARUMCashSalesDesk.Id);
    }

    SalesTable_ds.executeQuery();

    element.registerSetControlFocusAsync();

    return ret;
}

/// <summary>
/// Clicked method for the post button.
/// </summary>
public void clicked()
{
    if (CashSalesTotals_GrossAmount.realValue()>CashSalesTotals_GivenAmount.realValue())
    {
        error("@AVARUM:AVARUMCashSalesMsg1");
    }
    else
    {
        //super();
        Args args=new Args();
        MenuFunction mf=new MenuFunction(menuItemActionStr(AVARUMCashSalesPost), MenuItemType::Action);
        args.parmObject(cashSalesDeskManager);
        args.record(AVARUMCashSalesDesk);
        mf.run(args);                

        cashSalesDeskManager.resetAfterPost();
        element.refreshContext();
    }
}

/// <summary>
/// Modified method for the input control
/// </summary>
/// <returns>true/false</returns>
public boolean modified()
{
    boolean ret;

    ret = super();      

    InputCtrl.allowEdit(false);  // block until line is processed
    if (myUrlParam=='1')  //TST
    {
        element.setTimeoutEx(formMethodStr(AVARUMCashSales, handleInputAsync), conNull(), 5);
    }
    else if (myUrlParam=='2')  //TST
    {
        element.handleInput();
    }
    else
    {
        str input=InputCtrl.text();
        input=strltrim(strLRTrim(input));

        element.parmCashSalesDeskManager().processInput(SalesTable.SalesId, input);

        InputCtrl.text(AVAConstants::emptyString);

        SalesTable_DS.research(true);
        InputCtrl.allowEdit(true);

        element.registerSetControlFocusAsync();
    }

    return ret;
}
